import { createContext, useContext } from 'react'
import { createStore, StoreApi, useStore } from 'zustand'
import {
    ColumnFiltersState,
    ColumnPinningState,
    RowSelectionState,
    SortingState,
    Table,
    VisibilityState,
} from '@tanstack/react-table'

export interface RowGroup<TData> {
    predicate: (data: TData) => boolean
    separatorLabel?: string
}

type Updater<T> = T | ((prev: T) => T)

function applyUpdater<T>(updater: Updater<T>, prev: T): T {
    return typeof updater === 'function' ? (updater as (prev: T) => T)(prev) : updater
}

export interface DataTableStoreState {
    sorting: SortingState
    setSorting: (updater: Updater<SortingState>) => void
    columnFilters: ColumnFiltersState
    setColumnFilters: (updater: Updater<ColumnFiltersState>) => void
    columnVisibility: VisibilityState
    setColumnVisibility: (updater: Updater<VisibilityState>) => void
    rowSelection: RowSelectionState
    setRowSelection: (updater: Updater<RowSelectionState>) => void
    columnPinning: ColumnPinningState
    setColumnPinning: (updater: Updater<ColumnPinningState>) => void
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    rowGroup: RowGroup<any> | undefined
}

export function createDataTableStore(initial: {
    columnPinning: ColumnPinningState
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    rowGroup: RowGroup<any> | undefined
}) {
    return createStore<DataTableStoreState>((set) => ({
        sorting: [],
        setSorting: (u) => set((s) => ({ sorting: applyUpdater(u, s.sorting) })),
        columnFilters: [],
        setColumnFilters: (u) => set((s) => ({ columnFilters: applyUpdater(u, s.columnFilters) })),
        columnVisibility: {},
        setColumnVisibility: (u) => set((s) => ({ columnVisibility: applyUpdater(u, s.columnVisibility) })),
        rowSelection: {},
        setRowSelection: (u) => set((s) => ({ rowSelection: applyUpdater(u, s.rowSelection) })),
        columnPinning: initial.columnPinning,
        setColumnPinning: (u) => set((s) => ({ columnPinning: applyUpdater(u, s.columnPinning) })),
        rowGroup: initial.rowGroup,
    }))
}

export const DataTableStoreContext = createContext<StoreApi<DataTableStoreState> | null>(null)
// Wrapped in an object so a fresh reference is provided on every render. The `Table`
// instance from useReactTable is stable and mutated in place, so passing it directly
// would make React bail out of notifying context consumers when its internal state
// (sorting, visibility, etc.) changes.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const DataTableInstanceContext = createContext<{ table: Table<any> } | null>(null)

export function useDataTableStore<T>(selector: (state: DataTableStoreState) => T): T {
    const store = useContext(DataTableStoreContext)
    if (!store) throw new Error('useDataTableStore must be used within DataTableProvider')
    return useStore(store, selector)
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function useDataTable<TData = any>(): Table<TData> {
    const ctx = useContext(DataTableInstanceContext)
    if (!ctx) throw new Error('useDataTable must be used within DataTableProvider')
    return ctx.table as Table<TData>
}

import {
    ColumnDef,
    getCoreRowModel,
    getFilteredRowModel,
    getSortedRowModel,
    Row,
    RowData,
    useReactTable,
} from '@tanstack/react-table'
import { ReactNode, useEffect, useState } from 'react'
import { useStore } from 'zustand'
import {
    createDataTableStore,
    DataTableInstanceContext,
    DataTableStoreContext,
    RowGroup,
} from './data-table-context'

function buildInitialPinning<TData, TValue>(columns: ColumnDef<TData, TValue>[]) {
    const left: string[] = []
    const right: string[] = []
    for (const col of columns) {
        const pin = col.meta?.pin
        const id = (col as { id?: string }).id ?? (col as { accessorKey?: string }).accessorKey
        if (!id || !pin) continue
        if (pin === 'left') left.push(id)
        else right.push(id)
    }
    return { left, right }
}

interface DataTableProviderProps<TData extends RowData, TValue> {
    data: TData[]
    columns: ColumnDef<TData, TValue>[]
    enableRowSelection?: boolean | ((row: Row<TData>) => boolean)
    rowGroup?: RowGroup<TData>
    children: ReactNode
    getStore?: (store: ReturnType<typeof createDataTableStore>) => void  
}

export function DataTableProvider<TData extends RowData, TValue>({
    data,
    columns,
    enableRowSelection,
    rowGroup,
    children,
    getStore,
}: Readonly<DataTableProviderProps<TData, TValue>>) {
    const [store] = useState(() =>
        createDataTableStore({
            columnPinning: buildInitialPinning(columns),
            rowGroup,
        })
    )
    useEffect(() => {
        store.setState({ rowGroup })
        getStore?.(store)
    }, [store, rowGroup, getStore])

    const sorting = useStore(store, (s) => s.sorting)
    const setSorting = useStore(store, (s) => s.setSorting)
    const columnFilters = useStore(store, (s) => s.columnFilters)
    const setColumnFilters = useStore(store, (s) => s.setColumnFilters)
    const columnVisibility = useStore(store, (s) => s.columnVisibility)
    const setColumnVisibility = useStore(store, (s) => s.setColumnVisibility)
    const rowSelection = useStore(store, (s) => s.rowSelection)
    const setRowSelection = useStore(store, (s) => s.setRowSelection)
    const columnPinning = useStore(store, (s) => s.columnPinning)
    const setColumnPinning = useStore(store, (s) => s.setColumnPinning)

    const table = useReactTable<TData>({
        data,
        columns,
        getCoreRowModel: getCoreRowModel(),
        onSortingChange: setSorting,
        getSortedRowModel: getSortedRowModel(),
        onColumnFiltersChange: setColumnFilters,
        getFilteredRowModel: getFilteredRowModel(),
        onColumnVisibilityChange: setColumnVisibility,
        onColumnPinningChange: setColumnPinning,
        enableRowSelection: enableRowSelection ?? true,
        onRowSelectionChange: setRowSelection,
        state: {
            sorting,
            columnFilters,
            columnVisibility,
            columnPinning,
            rowSelection,
        },
    })
    return (
        <DataTableStoreContext.Provider value={store}>
            <DataTableInstanceContext.Provider value={{ table }}>
                {children}
            </DataTableInstanceContext.Provider>
        </DataTableStoreContext.Provider>
    )
}

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { RowGroup, useDataTable, useDataTableStore } from './data-table-context'
import { cn } from '@/lib/utils'
import { Column, flexRender, Row, RowData, Table as TableType } from '@tanstack/react-table'
import { useVirtualizer } from '@tanstack/react-virtual'
import { CSSProperties, RefObject, useEffect, useRef, useState } from 'react'

declare module '@tanstack/react-table' {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    interface ColumnMeta<TData extends RowData, TValue> {
        pin?: 'left' | 'right'
        toggleVisibility?: boolean
    }
}

function getPinnedStyles<TData>(column: Column<TData>): CSSProperties {
    const isPinned = column.getIsPinned()
    if (!isPinned) return {}
    return {
        position: 'sticky',
        left: isPinned === 'left' ? column.getStart('left') : undefined,
        right: isPinned === 'right' ? column.getAfter('right') : undefined,
        zIndex: 1,
        backgroundColor: 'hsl(var(--background))',
    }
}

export function DataTable() {
    const table = useDataTable()
    useEffect(()=>{
        console.log('Table changed')
        console.log(table.getAllColumns())
    },[table])
    const rowGroup = useDataTableStore((s) => s.rowGroup)

    const tableContainerRef = useRef<HTMLDivElement>(null)
    const outerRef = useRef<HTMLDivElement>(null)
    const [containerWidth, setContainerWidth] = useState<number | undefined>(undefined)
    const [widthCalculated, setWidthCalculated] = useState(false)

    useEffect(() => {
        const el = outerRef.current
        if (!el) return
        const observer = new ResizeObserver(([entry]) => setContainerWidth(entry.contentRect.width))
        observer.observe(el)
        setWidthCalculated(true)
        return () => observer.disconnect()
    }, [])

    return (
        <div className="flex-1 min-w-0 min-h-0 overflow-hidden border rounded-md" ref={outerRef}>
            {widthCalculated && (
                // The virtualizer measures scroll against this element, so the
                // item owns its scroll container rather than relying on the one
                // stock shadcn <Table> hardcodes (that one is overflow-x only
                // and exposes no ref).
                <div
                    ref={tableContainerRef}
                    className="relative h-full overflow-auto"
                    style={{ width: containerWidth }}
                >
                <Table
                    className="table-fixed"
                    style={{ minWidth: table.getTotalSize() }}
                >
                    <TableHeader className="sticky top-0 z-10 bg-background">
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow key={headerGroup.id}>
                                {headerGroup.headers.map((header) => (
                                    <TableHead
                                        key={header.id}
                                        style={{
                                            width: header.getSize(),
                                            ...getPinnedStyles(header.column),
                                            zIndex: header.column.getIsPinned() ? 20 : undefined,
                                        }}
                                        className={cn(header.column.getIsPinned() && 'border-l')}
                                    >
                                        {header.isPlaceholder
                                            ? null
                                            : flexRender(header.column.columnDef.header, header.getContext())}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <VirtualizedTableBody
                        table={table}
                        tableContainerRef={tableContainerRef}
                        rowGroup={rowGroup}
                    />
                </Table>
                </div>
            )}
        </div>
    )
}

type VirtualItem<TData> = { type: 'row'; row: Row<TData> } | { type: 'separator'; label?: string }

interface VirtualizedTableBodyProps<TData> {
    table: TableType<TData>
    tableContainerRef: RefObject<HTMLDivElement | null>
    rowGroup?: RowGroup<TData>
}

function VirtualizedTableBody<TData>({
    table,
    tableContainerRef: ref,
    rowGroup,
}: Readonly<VirtualizedTableBodyProps<TData>>) {
    const { rows } = table.getRowModel()

    const virtualItems: VirtualItem<TData>[] = rowGroup
        ? (() => {
              const primary: VirtualItem<TData>[] = []
              const secondary: VirtualItem<TData>[] = []
              for (const row of rows) {
                  if (rowGroup.predicate(row.original)) {
                      secondary.push({ type: 'row', row })
                  } else {
                      primary.push({ type: 'row', row })
                  }
              }
              if (primary.length > 0 && secondary.length > 0) {
                  return [...primary, { type: 'separator', label: rowGroup.separatorLabel }, ...secondary]
              }
              return [...primary, ...secondary]
          })()
        : rows.map((row) => ({ type: 'row' as const, row }))

    const rowVirtualizer = useVirtualizer<HTMLDivElement, HTMLTableRowElement>({
        count: virtualItems.length,
        estimateSize: (i) => (virtualItems[i]?.type === 'separator' ? 36 : 45),
        getScrollElement: () => ref?.current,
        overscan: 5,
        measureElement:
            globalThis.window !== undefined && navigator.userAgent.indexOf('Firefox') === -1
                ? (element) => element?.getBoundingClientRect().height
                : undefined,
    })

    const virtualRows = rowVirtualizer.getVirtualItems()
    const paddingTop = virtualRows.length > 0 ? virtualRows[0].start : 0
    const paddingBottom =
        virtualRows.length > 0 ? rowVirtualizer.getTotalSize() - (virtualRows.at(-1)?.end ?? 0) : 0
    // Visible leaf columns, not all columns — otherwise the empty/separator row
    // spans too far once any column is hidden via columnDef.meta.toggleVisibility.
    const colSpan = table.getVisibleLeafColumns().length

    return (
        <TableBody>
            {virtualRows.length ? (
                <>
                    {paddingTop > 0 && (
                        <TableRow>
                            <TableCell colSpan={colSpan} style={{ height: paddingTop, padding: 0 }} />
                        </TableRow>
                    )}
                    {virtualRows.map((virtualRow) => {
                        const item = virtualItems[virtualRow.index]
                        if (item.type === 'separator') {
                            return (
                                <TableRow
                                    key="group-separator"
                                    data-index={virtualRow.index}
                                    ref={rowVirtualizer.measureElement}
                                >
                                    <TableCell colSpan={colSpan} className="py-1.5 px-3 bg-muted/50">
                                        <div className="flex items-center gap-2">
                                            <div className="flex-1 h-px bg-border" />
                                            {item.label && (
                                                <span className="text-xs text-muted-foreground whitespace-nowrap">
                                                    {item.label}
                                                </span>
                                            )}
                                            <div className="flex-1 h-px bg-border" />
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )
                        }
                        const { row } = item
                        return (
                            <TableRow
                                key={row.id}
                                data-state={row.getIsSelected() && 'selected'}
                                data-index={virtualRow.index}
                                ref={rowVirtualizer.measureElement}
                            >
                                {row.getVisibleCells().map((cell) => (
                                    <TableCell key={cell.id} style={getPinnedStyles(cell.column)}>
                                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                    </TableCell>
                                ))}
                            </TableRow>
                        )
                    })}
                    {paddingBottom > 0 && (
                        <TableRow>
                            <TableCell colSpan={colSpan} style={{ height: paddingBottom, padding: 0 }} />
                        </TableRow>
                    )}
                </>
            ) : (
                <TableRow>
                    <TableCell colSpan={colSpan} className="h-24 text-center">
                        No results.
                    </TableCell>
                </TableRow>
            )}
        </TableBody>
    )
}

import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group'
import { useDataTable } from './data-table-context'
import { Search } from 'lucide-react'
import { parseAsString, useQueryState } from 'nuqs'
import { useEffect, useRef } from 'react'

interface DataTableSearchProps {
    columnName: string
    /** nuqs URL param key. Defaults to columnName. Use a unique key when multiple tables share a page. */
    queryKey?: string
    placeholder?: string
    className?: string
}

export function DataTableSearch({
    columnName,
    queryKey,
    placeholder = 'Search...',
    className,
}: Readonly<DataTableSearchProps>) {
    const table = useDataTable()
    const [value, setValue] = useQueryState(queryKey ?? columnName, parseAsString)

    // Use a ref so the effect doesn't re-run every time the table instance changes
    // (useReactTable returns a new object each render)
    const tableRef = useRef(table)
    tableRef.current = table

    useEffect(() => {
        tableRef.current.getColumn(columnName)?.setFilterValue(value ?? undefined)
    }, [value, columnName])

    const resultCount = table.getFilteredRowModel().rows.length

    return (
        <InputGroup className={className}>
            <InputGroupInput
                placeholder={placeholder}
                value={value ?? ''}
                onChange={(e) => setValue(e.target.value || null)}
            />
            <InputGroupAddon>
                <Search />
            </InputGroupAddon>
            <InputGroupAddon align="inline-end" className="text-xs">
                {(value?.trim().length ?? 0) > 0 && `${resultCount} results`}
            </InputGroupAddon>
        </InputGroup>
    )
}

import React, { ReactNode, useState } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { Filter } from 'lucide-react';
import { Table as TableType } from '@tanstack/react-table';
import {
    Combobox,
    ComboboxChip,
    ComboboxChips,
    ComboboxChipsInput,
    ComboboxContent,
    ComboboxEmpty,
    ComboboxItem,
    ComboboxList,
    ComboboxValue,
    useComboboxAnchor,
} from '@/registry/combobox/components/combobox';

/**
 * A single entry in the filters popover.
 *
 * `component` is rendered as-is, so a filter can be anything — this file ships
 * two builders for the common shapes, but an app is expected to write its own
 * domain-specific builders and pass them in alongside.
 */
export interface TableFilterOption {
    key: string;
    isActive: boolean;
    /** When set, contributes this number to the indicator instead of 1/0 from isActive. */
    activeCount?: number;
    component: ReactNode;
}

interface TableFiltersPopoverProps {
    filters: TableFilterOption[];
}

/**
 * The generic shell: a trigger button with an active-filter count badge, and a
 * popover that renders each filter's component separated by dividers.
 *
 * It knows nothing about what the filters do — that is entirely in the
 * `component` each option supplies.
 */
export function TableFiltersPopover({ filters }: Readonly<TableFiltersPopoverProps>) {
    const activeCount = filters.reduce((sum, f) => sum + (f.activeCount ?? (f.isActive ? 1 : 0)), 0);

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="relative gap-2">
                    <Filter className="size-4" />
                    Filters
                    {activeCount > 0 && (
                        <div className="absolute top-0 right-0 grid p-0 px-1 text-xs text-white bg-red-500 rounded-3xl min-w-4 translate-x-1/3 -translate-y-1/3 place-items-center">
                            {activeCount}
                        </div>
                    )}
                </Button>
            </PopoverTrigger>
            <PopoverContent align="start" className="w-auto min-w-56">
                <div className="flex flex-col gap-3">
                    {filters.map((filter, i) => (
                        <React.Fragment key={filter.key}>
                            {filter.component}
                            {i < filters.length - 1 && <Separator />}
                        </React.Fragment>
                    ))}
                </div>
            </PopoverContent>
        </Popover>
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Generic builders
//
// These cover the two shapes that come up constantly. Anything domain-specific
// (filtering by a CRM system, a connection, a tenant…) belongs in your app as
// its own `build*Filter` function returning a TableFilterOption.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A single on/off checkbox bound to a column's filter value.
 *
 * Sets the filter to `true` when checked and `undefined` when not, so an
 * unchecked box removes the filter rather than filtering for `false`.
 */
export function buildCheckboxFilter<TData>({
    table,
    columnId,
    label,
}: {
    table: TableType<TData>;
    columnId: string;
    label: string;
}): TableFilterOption {
    const isActive = !!table.getColumn(columnId)?.getFilterValue();
    const inputId = `${columnId}-filter`;

    return {
        key: columnId,
        isActive,
        component: (
            <div className="flex items-center gap-2">
                <Checkbox
                    id={inputId}
                    checked={isActive}
                    onCheckedChange={(checked) => {
                        table.getColumn(columnId)?.setFilterValue(checked || undefined);
                    }}
                    className="size-5"
                />
                <Label htmlFor={inputId} className="text-sm cursor-pointer">
                    {label}
                </Label>
            </div>
        ),
    };
}

export interface MultiSelectFilterOption<TId extends string | number> {
    id: TId;
    name: string | null;
}

function MultiSelectFilterContent<TId extends string | number>({
    label,
    options,
    value,
    onChange,
    emptyMessage,
}: {
    label: string;
    options: MultiSelectFilterOption<TId>[];
    value: TId[];
    onChange: (value: TId[]) => void;
    emptyMessage: string;
}) {
    const anchor = useComboboxAnchor();
    const [selected, setSelected] = useState<TId[]>(value);

    const handleChange = (vals: TId[]) => {
        setSelected(vals);
        onChange(vals);
    };

    return (
        <div className="flex flex-col gap-2" ref={anchor}>
            <p className="text-xs font-medium tracking-wide uppercase text-muted-foreground">{label}</p>
            <Combobox
                multiple
                autoHighlight
                items={options}
                // Base UI infers the item type from `value` (TId[]) rather than
                // `items` once the option type is generic, so this widens first.
                itemToStringValue={(o: unknown) => (o as MultiSelectFilterOption<TId>).name ?? ''}
                value={selected}
                onValueChange={(vals) => handleChange(vals as TId[])}
            >
                <ComboboxChips className="w-full max-w-xs">
                    <ComboboxValue>
                        <>
                            {selected.map((id) => (
                                <ComboboxChip key={id}>
                                    {options.find((o) => o.id === id)?.name ?? id}
                                </ComboboxChip>
                            ))}
                        </>
                        <ComboboxChipsInput />
                    </ComboboxValue>
                </ComboboxChips>
                <ComboboxContent anchor={anchor} className={'overflow-y-scroll'}>
                    <ComboboxList>
                        {(item) => {
                            const option = item as MultiSelectFilterOption<TId>;
                            return (
                                <ComboboxItem key={option.id} value={option.id}>
                                    {option.name ?? option.id}
                                </ComboboxItem>
                            );
                        }}
                    </ComboboxList>
                    <ComboboxEmpty>{emptyMessage}</ComboboxEmpty>
                </ComboboxContent>
            </Combobox>
        </div>
    );
}

/**
 * A multi-select combobox bound to a column's filter value, rendering the
 * selection as removable chips.
 *
 * `activeCount` reports the number of selected values so the popover badge
 * counts each selection rather than counting the whole filter as one.
 */
export function buildMultiSelectFilter<TData, TId extends string | number>({
    table,
    columnId,
    label,
    options,
    emptyMessage = 'No options',
}: {
    table: TableType<TData>;
    columnId: string;
    label: string;
    options: MultiSelectFilterOption<TId>[];
    emptyMessage?: string;
}): TableFilterOption {
    const filterValue = (table.getColumn(columnId)?.getFilterValue() as TId[] | undefined) ?? [];

    return {
        key: columnId,
        isActive: filterValue.length > 0,
        activeCount: filterValue.length,
        component: (
            <MultiSelectFilterContent
                label={label}
                options={options}
                value={filterValue}
                emptyMessage={emptyMessage}
                onChange={(vals) => {
                    table.getColumn(columnId)?.setFilterValue(vals.length ? vals : undefined);
                }}
            />
        ),
    };
}
